import { useEffect, useCallback } from 'react';

export interface KeyboardShortcuts {
    onSelectAll?: () => void;
    onCopy?: () => void;
    onPaste?: () => void;
    onDelete?: () => void;
    onUndo?: () => void;
    onRedo?: () => void;
    onDuplicate?: () => void;
    onEscape?: () => void;
    onNudgeUp?: () => void;
    onNudgeDown?: () => void;
    onNudgeLeft?: () => void;
    onNudgeRight?: () => void;
}

export function useKeyboardShortcuts(shortcuts: KeyboardShortcuts, enabled: boolean = true) {
    const handleKeyDown = useCallback((event: KeyboardEvent) => {
        if (!enabled) return;

        const { ctrlKey, metaKey, key, shiftKey } = event;
        const isModifier = ctrlKey || metaKey; // Support both Ctrl (Windows) and Cmd (Mac)

        // Ctrl/Cmd + A: Select All
        if (isModifier && key === 'a' && shortcuts.onSelectAll) {
            event.preventDefault();
            shortcuts.onSelectAll();
            return;
        }

        // Ctrl/Cmd + C: Copy
        if (isModifier && key === 'c' && shortcuts.onCopy) {
            event.preventDefault();
            shortcuts.onCopy();
            return;
        }

        // Ctrl/Cmd + V: Paste
        if (isModifier && key === 'v' && shortcuts.onPaste) {
            event.preventDefault();
            shortcuts.onPaste();
            return;
        }

        // Delete or Backspace: Delete
        if ((key === 'Delete' || key === 'Backspace') && shortcuts.onDelete) {
            event.preventDefault();
            shortcuts.onDelete();
            return;
        }

        // Ctrl/Cmd + Z: Undo
        if (isModifier && key === 'z' && !shiftKey && shortcuts.onUndo) {
            event.preventDefault();
            shortcuts.onUndo();
            return;
        }

        // Ctrl/Cmd + Y or Ctrl/Cmd + Shift + Z: Redo
        if ((isModifier && key === 'y') || (isModifier && shiftKey && key === 'z')) {
            if (shortcuts.onRedo) {
                event.preventDefault();
                shortcuts.onRedo();
            }
            return;
        }

        // Ctrl/Cmd + D: Duplicate
        if (isModifier && key === 'd' && shortcuts.onDuplicate) {
            event.preventDefault();
            shortcuts.onDuplicate();
            return;
        }

        // Escape: Clear selection
        if (key === 'Escape' && shortcuts.onEscape) {
            event.preventDefault();
            shortcuts.onEscape();
            return;
        }

        // Arrow keys: Nudge (only if not in input field)
        const target = event.target as HTMLElement;
        const isInputField = target.tagName === 'INPUT' || target.tagName === 'TEXTAREA';

        if (!isInputField) {
            const nudgeAmount = shiftKey ? 10 : 1; // Shift = larger nudge

            if (key === 'ArrowUp' && shortcuts.onNudgeUp) {
                event.preventDefault();
                for (let i = 0; i < nudgeAmount; i++) shortcuts.onNudgeUp();
                return;
            }

            if (key === 'ArrowDown' && shortcuts.onNudgeDown) {
                event.preventDefault();
                for (let i = 0; i < nudgeAmount; i++) shortcuts.onNudgeDown();
                return;
            }

            if (key === 'ArrowLeft' && shortcuts.onNudgeLeft) {
                event.preventDefault();
                for (let i = 0; i < nudgeAmount; i++) shortcuts.onNudgeLeft();
                return;
            }

            if (key === 'ArrowRight' && shortcuts.onNudgeRight) {
                event.preventDefault();
                for (let i = 0; i < nudgeAmount; i++) shortcuts.onNudgeRight();
                return;
            }
        }
    }, [shortcuts, enabled]);

    useEffect(() => {
        if (!enabled) return;

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [handleKeyDown, enabled]);
}
